"use strict";
// VERSION and FILES are generated by npm run build from the deployable shell.
const VERSION = "7ef79e5533b96521";
const BASE = new URL("./", self.location.href);
const PREFIX = "edu-manager:" + BASE.pathname + ":";
const CACHE = PREFIX + VERSION;
const STAGING = CACHE + ":staging";
const FILES = [
  "EduManager.html",
  "index.html",
  "app.webmanifest",
  "assets/scripts/data-store-schema.js",
  "assets/scripts/data-store-runtime.js",
  "assets/scripts/data-store.js",
  "assets/scripts/runtime-api.js",
  "assets/scripts/grade-math.js",
  "assets/scripts/data-boundary.js",
  "assets/scripts/calendar-math.js",
  "assets/scripts/calendar-ui.js",
  "assets/scripts/legacy-ui.js",
  "assets/scripts/csv-parser.js",
  "assets/scripts/password-service.js",
  "assets/scripts/dialogs-ui.js",
  "assets/scripts/grade-policy.js",
  "assets/scripts/course-ui.js",
  "assets/scripts/workspace-records.js",
  "assets/scripts/history-changes.js",
  "assets/scripts/record-commit-plan.js",
  "assets/scripts/record-transaction.js",
  "assets/scripts/full-backup-validator.js",
  "assets/scripts/frozen-report-validator.js",
  "assets/scripts/undo-validator.js",
  "assets/scripts/grade-drafts.js",
  "assets/scripts/workspace-runtime.js",
  "assets/scripts/pwa-manifest.js",
  "assets/scripts/app-shell-ui.js",
  "assets/scripts/pwa-ui.js",
  "assets/scripts/periodic-reports.js",
  "assets/styles/app.css",
  "assets/styles/daily-workflow.css",
  "assets/scripts/data-store-schema.js.map",
  "assets/scripts/data-store-runtime.js.map",
  "assets/scripts/data-store.js.map",
  "assets/scripts/runtime-api.js.map",
  "assets/scripts/grade-math.js.map",
  "assets/scripts/data-boundary.js.map",
  "assets/scripts/calendar-math.js.map",
  "assets/scripts/calendar-ui.js.map",
  "assets/scripts/legacy-ui.js.map",
  "assets/scripts/csv-parser.js.map",
  "assets/scripts/password-service.js.map",
  "assets/scripts/dialogs-ui.js.map",
  "assets/scripts/grade-policy.js.map",
  "assets/scripts/course-ui.js.map",
  "assets/scripts/workspace-records.js.map",
  "assets/scripts/history-changes.js.map",
  "assets/scripts/record-commit-plan.js.map",
  "assets/scripts/record-transaction.js.map",
  "assets/scripts/full-backup-validator.js.map",
  "assets/scripts/frozen-report-validator.js.map",
  "assets/scripts/undo-validator.js.map",
  "assets/scripts/grade-drafts.js.map",
  "assets/scripts/workspace-runtime.js.map",
  "assets/scripts/pwa-manifest.js.map",
  "assets/scripts/app-shell-ui.js.map",
  "assets/scripts/pwa-ui.js.map",
  "assets/scripts/periodic-reports.js.map",
  "assets/styles/app.css.map",
  "assets/styles/daily-workflow.css.map"
];
const URLS = FILES.map((name) => new URL(name, BASE).href);
const APP = new URL("EduManager.html", BASE).href;
let activationReady = Promise.resolve();

self.addEventListener("install", (event) =>
  event.waitUntil(
    (async () => {
      // Installation failure never removes the previous active cache.
      await caches.delete(STAGING);
      const cache = await caches.open(STAGING);
      try {
        for (const url of URLS) {
          const response = await fetch(
            new Request(url, { cache: "reload", credentials: "same-origin" }),
          );
          if (!response.ok || response.redirected || response.type === "opaque")
            throw Error("Incomplete offline download");
          await cache.put(url, response);
        }
      } catch (error) {
        await caches.delete(STAGING);
        throw error;
      }
    })(),
  ),
);

self.addEventListener("activate", (event) => {
  activationReady = (async () => {
    const staging = await caches.open(STAGING);
    const responses = await Promise.all(URLS.map((url) => staging.match(url)));
    if (!responses.every(Boolean))
      throw Error("Offline installation is incomplete");
    const cache = await caches.open(CACHE);
    for (let i = 0; i < URLS.length; i++)
      await cache.put(URLS[i], responses[i]);
    for (const key of await caches.keys()) {
      if (key.startsWith(PREFIX) && key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })();
  event.waitUntil(activationReady);
});

self.addEventListener("fetch", (event) => {
  if (event.request.method !== "GET") return;
  const url = new URL(event.request.url);
  if (url.origin !== BASE.origin) return;
  const navigation =
    event.request.mode === "navigate" &&
    [
      BASE.pathname,
      new URL("index.html", BASE).pathname,
      new URL("EduManager.html", BASE).pathname,
    ].includes(url.pathname);
  if (navigation || URLS.includes(url.href)) {
    event.respondWith(
      (async () => {
        await activationReady;
        const cache = await caches.open(CACHE);
        return (
          (await cache.match(navigation ? APP : event.request)) ||
          fetch(event.request)
        );
      })(),
    );
  }
});

self.addEventListener("message", (event) => {
  if (event.data?.type === "OFFLINE_STATUS")
    event.waitUntil(
      (async () => {
        // A new controller can receive messages before activation finishes promoting files.
        await activationReady;
        const cache = await caches.open(CACHE);
        const ready = (
          await Promise.all(URLS.map((url) => cache.match(url)))
        ).every(Boolean);
        event.ports[0]?.postMessage({ ready, version: VERSION });
      })(),
    );
  if (event.data?.type === "APPLY_UPDATE") event.waitUntil(self.skipWaiting());
});
